<h1><?= $mode==='templates'?'قالب‌های اعلان':'سوابق اعلان' ?></h1><p class="notice">اعلان درون سامانه واقعاً ذخیره می‌شود. ارسال اعلان ایتا هنوز فعال نیست. پیامک فقط برای کد احراز هویت استفاده می‌شود.</p>
<?php if($mode==='templates'): ?><section class="card section"><h2>ساخت نسخه قالب</h2><p>متغیرهای مجاز: <code>{display_name}</code> و <code>{message}</code>. نسخه قبلی تغییر نمی‌کند.</p><?= $this->start('/notification-templates/create') ?><?= $this->field('name','نام قالب') ?><?= $this->field('title','عنوان اعلان') ?><label for="template-body">متن</label><textarea id="template-body" name="body" rows="6" required><?= $this->val('body') ?></textarea><button>ذخیره نسخه قالب</button></form></section>
<section class="card section"><h2>ارسال اعلان درون سامانه</h2><?= $this->start('/notification-deliveries/send') ?><input type="hidden" name="request_key" value="<?= $this->val('request_key',bin2hex(random_bytes(16))) ?>"><label>قالب<select name="template_id"><?php foreach($rows as $r): ?><option value="<?= $this->h($r['id']) ?>"><?= $this->h($r['name']) ?> · <?= $this->h($r['id']) ?></option><?php endforeach; ?></select></label><?= $this->field('user_id','شناسه داخلی مخاطب') ?><label for="delivery-message">متن متغیر message</label><textarea id="delivery-message" name="message" rows="4"><?= $this->val('message') ?></textarea><button>ذخیره اعلان برای مخاطب</button></form></section>
<?php foreach($rows as $r): ?><article class="card section"><h2><?= $this->h($r['name']) ?></h2><p><?= $this->h($r['title']) ?></p><p class="prose"><?= nl2br($this->h($r['body'])) ?></p><code><?= $this->h($r['id']) ?></code></article><?php endforeach; ?>
<?php else:foreach($rows as $r): ?><article class="card section"><p>مخاطب: <?= $this->h($r['user_id']) ?></p><p>قالب: <?= $this->h($r['template_id']) ?></p><p>کانال: <?= $this->status($r['channel']) ?> · وضعیت: <?= $this->status($r['state']) ?></p><p>شناسه اعلان: <?= $this->h($r['notification_id']) ?></p></article><?php endforeach;endif; ?>
